class Solution {public:int solve(vector<int> values,long long limit){deque<int> hi,lo;int left=0,best=0;for(int right=0;right<(int)values.size();right++){while(!hi.empty()&&values[hi.back()]<=values[right])hi.pop_back();while(!lo.empty()&&values[lo.back()]>=values[right])lo.pop_back();hi.push_back(right);lo.push_back(right);while(1LL*values[hi.front()]-values[lo.front()]>limit){left++;if(hi.front()<left)hi.pop_front();if(lo.front()<left)lo.pop_front();}best=max(best,right-left+1);}return best;}};